// WithTx rebinds every accessor to tx.
func (store) WithTx(tx orm.Context) Store { return NewStore(tx) }

// NewStore returns the aggregate store bound to db. Pass the *orm.Client
// for ordinary use, or a transaction handle to scope every call to it.
func NewStore(db orm.Context) Store { return store{db: db} }

var _ Store = store{}
